# Code generated by Claude
"""
Force disturbances of the base during the staging (src/staging_source.py) and check what the staging does.

    MUJOCO_GL=egl python experiments/beaker_hotplate_correction_test.py

Staging order since 2026-10-19 (David: the arms stay at home at all times except during manipulation): ARMS and PEDESTAL at the spawn in open space, then DRIVE to the approach
spot and CREEP_IN to the staging pose with the arms at home. The old pose-correction phases after the pedestal and arm moves are gone (nothing moves the base after the drive).
Each case runs a headless episode with the test-only kick source (experiments/episode_test_sources.make_kick_source), which displaces the base at a chosen moment, and with a copy of
the config where needed. Episodes are short after HANDOFF (3 s). "corrected" = the episode reached the handoff within the drive tolerance (drive_pos_tol, drive_yaw_tol).
  1. kick during PEDESTAL (25 mm sideways, 5 deg, at the spawn): the DRIVE that follows starts from wherever the base is                   -> corrected
  2. kick during CREEP_IN, 12 mm toward the bench + 1.5 deg: the creep absorbs the along error and steers the yaw away                   -> corrected
  3. kick during CREEP_IN, 10 mm away from the bench - 1.5 deg                                                                         -> corrected
  4. kick during CREEP_IN, 30 mm along (the old limit of 20 mm no longer applies: the creep aims at the goal all the time)              -> corrected
  5. kick during CREEP_IN, 15 mm sideways: cannot be corrected without a large turn (the final check fails)                            -> STAGING_FAILED
  6. as 2 with correction_arms_min_arm_clearance = 0.5 m: the clearance guard trips while driving                                       -> STAGING_FAILED
  7. kick during CREEP_IN, 2.5 deg of yaw (> correction_arms_max_yaw = 2 deg)                                                          -> STAGING_FAILED
  8. arms_open_space_min_clearance = 5 m: the spawn is "not open space" for the arm move, the ARMS check fails before anything moves    -> STAGING_FAILED, arms not moved
  9. drive_max_lean_deg = 0.0001: the lean check trips while driving with the arms out                                                  -> STAGING_FAILED
"""

import copy
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

from src.task_beaker_hotplate import run_beaker_episode as run_episode  # noqa: E402
from episode_test_sources import make_kick_source  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import EPISODE_CFG, STAGING_CFG  # noqa: E402

CASES = [
    ("1 pedestal kick 25 mm sideways + 5 deg (at the spawn)", ("PEDESTAL", 2.0, 0.0, 25.0, 5.0), {}, "corrected"),
    ("2 creep-in kick 12 mm toward bench + 1.5 deg", ("CREEP_IN", 5.0, 12.0, 0.0, 1.5), {}, "corrected"),
    ("3 creep-in kick 10 mm away from bench - 1.5 deg", ("CREEP_IN", 5.0, -10.0, 0.0, -1.5), {}, "corrected"),
    ("4 creep-in kick 30 mm along", ("CREEP_IN", 5.0, 30.0, 0.0, 0.0), {}, "corrected"),
    ("5 creep-in kick 15 mm sideways", ("CREEP_IN", 5.0, 0.0, 15.0, 0.0), {}, "failed"),
    ("6 as 2, arm clearance minimum 0.5 m", ("CREEP_IN", 5.0, 12.0, 0.0, 1.5), {"correction_arms_min_arm_clearance": 0.5}, "failed"),
    ("7 creep-in kick 2.5 deg of yaw (> correction_arms_max_yaw = 2 deg)", ("CREEP_IN", 5.0, 0.0, 0.0, 2.5), {}, "failed"),
    ("8 arms_open_space_min_clearance = 5 m", ("PEDESTAL", 99.0, 0.0, 0.0, 0.0), {"arms_open_space_min_clearance": 5.0}, "failed"),
    ("9 drive_max_lean_deg = 0.0001", ("PEDESTAL", 99.0, 0.0, 0.0, 0.0), {"drive_max_lean_deg": 0.0001}, "failed"),
]


def main():
    sim = load_task(cameras=True)
    model, data = sim.model, sim.data
    ep_cfg = {**EPISODE_CFG, "timeout_after_handoff": 3.0}
    n_ok = 0
    for name, (phase, delay, along, lateral, yaw), override, expect in CASES:
        cfg = {**copy.deepcopy(STAGING_CFG), **override}
        s = run_episode(None, model, data, staging_cfg=cfg, episode_cfg=ep_cfg,
                        extra_sources=lambda m, d: {"kick": make_kick_source(m, d, phase, delay, along, lateral, yaw)})
        e = s["base_pose_error_at_handoff"]
        within = e is not None and e["pos_err_mm"] <= 1000 * cfg["drive_pos_tol"] and abs(e["yaw_err_deg"]) <= __import__("math").degrees(cfg["drive_yaw_tol"])
        got = "failed" if s["outcome"] == "STAGING_FAILED" else ("corrected" if s["handoff_time"] is not None and within else "not corrected")
        ok = got == expect
        if name.startswith("8"):                                   # nothing may have moved: the arms are still at the rest pose and the base has not moved
            ok = ok and "ARMS" in (s["staging_error"] or "") and (s["phase_times"].get("PEDESTAL") is None)
        n_ok += ok
        print(f"\n{'PASS' if ok else 'FAIL'}  case {name}: outcome {s['outcome']} (expected {expect})")
        for c in s["pose_corrections"]:
            b, a = c["before"], c["after"]
            print(f"      {c['phase']:17s} {b['pos_mm']:5.1f} mm (along {b['along_mm']:+5.1f}, sideways {b['lateral_mm']:+5.1f}) {b['yaw_deg']:+5.2f} deg -> {a['pos_mm']:.1f} mm, {a['yaw_deg']:+.2f} deg in "
                  f"{c['duration_s']:.1f} s [{c['status']}]" + (f"; min clearance base {c['min_base_clearance_mm']:.0f} mm, arm {c['min_arm_clearance_mm']:.0f} mm" if c["min_arm_clearance_mm"] is not None else ""))
        if s["staging_error"]:
            print("      staging error:", s["staging_error"])
        if e:
            print(f"      pose error at HANDOFF {e['pos_err_mm']:.1f} mm / {e['yaw_err_deg']:+.2f} deg")
    print(f"\n{n_ok}/{len(CASES)} cases as expected")
    return n_ok == len(CASES)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
